;
/* ==== js/ship-res.js ==== */
HK.Load.def(244,'js/ship-res.js',function(){
(function(){
'use strict';
var HK=window.HK,SH=HK.SHIP=HK.SHIP||{};
SH.RES=[
{id:'ice',name:'氷晶の鉱脈',rare:1,use:'o2',sky:'極地から赤道へ向けて、白い筋が何本も地表を走っていた。陽を受けるたび、筋は細かくきらめいた。',hint:'{a}は岩の割れ目にのぞく青白い層を見つけた。手袋越しにも、しんとした冷たさが伝わってきた。',detail:'{a}が削り出した氷は、ほとんど混じり気のない水だった。分解すれば、船の空気を何か月も保てる量だと分かった。',deep:'鉱脈の奥で、{a}は氷に閉じ込められた古い空気の泡を見つけた。その組成は、この星にかつて濃い大気があったことを物語っていた。',item:'凍った泡の標本',itemDesc:'数億年前の空気を一粒だけ抱いた、親指ほどの氷の塊だった。',trouble:'{a}は氷の斜面で足を滑らせ、鉱脈の縁に膝を強く打ちつけた。',death:'氷の崖が音もなく崩れ、{v}は青白い塊の下に消えた。{w}が掘り出したとき、もう息はなかった。',report:'氷晶鉱脈の採取と水資源の見積もり'},
{id:'iron',name:'赤錆の鉄鉱床',rare:1,use:'hull',sky:'大陸の半分が、乾いた血のような赤茶色に染まっていた。その色は、地表を覆う酸化鉄の広がりを示していた。',hint:'{a}の靴底に、赤い粉が厚くまとわりついた。磁石を近づけると、粉はかすかに震えた。',detail:'{a}は錆の下に、ほとんど純粋な鉄の層が眠っているのを確かめた。精錬すれば、船体の補修板を十分に作れそうだった。',deep:'鉱床の底で、{a}は規則正しく並んだ鉄の柱を見つけた。自然にできたにしては、あまりにまっすぐだった。',item:'赤鉄の結晶柱',itemDesc:'六角形の断面をもつ、驚くほど重い赤黒い柱だった。',trouble:'{a}は錆びた岩の縁で腕を深く切り、しばらく作業を中断した。',death:'鉄鉱床の採掘坑が崩れ、{v}は赤い土砂に呑まれた。{w}の呼ぶ声に、応える者はいなかった。',report:'赤錆鉱床における鉄の精錬試験'},
{id:'salt',name:'塩の平原',rare:1,use:'food',sky:'地平線まで続く白い平原が、鏡のように空を映していた。雲の影だけが、その上をゆっくり横切っていった。',hint:'{a}がひとかけらを舐めると、舌がしびれるほど塩辛かった。足元の白は、すべて塩の結晶だった。',detail:'{a}の分析で、塩には船の食事に欠けていた微量の鉱物が含まれていると分かった。保存食の仕込みにも使えそうだった。',deep:'平原の中央で、{a}は塩の層に封じられた小さな魚の群れを見つけた。この星にも、かつて海があったのだ。',item:'塩漬けの化石魚',itemDesc:'透き通った塩の板の中で、銀色の小魚が泳ぐ姿のまま固まっていた。',trouble:'{a}は照り返しで目を痛め、数日のあいだ視界がにじんだままだった。',death:'塩の表面の下には、深い塩水のたまりが隠れていた。{v}は薄い殻を踏み抜き、二度と浮かんでこなかった。',report:'塩平原の鉱物組成と保存食への応用'},
{id:'clay',name:'甘い粘土',rare:1,use:'food',sky:'川沿いの低地に、淡い桃色の帯が細く伸びていた。雨のあとには、その色が少し濃くなるようだった。',hint:'{a}が掘り返した粘土は、ほのかに果物のような匂いを放っていた。',detail:'{a}は、粘土に糖とでんぷんに似た成分が染み込んでいるのを確かめた。よく洗って焼けば、食べられる団子になった。',deep:'地層を掘り進めた{a}は、粘土が地下の植物の根から少しずつ滲み出た養分でできていると知った。星そのものが、誰かを養おうとしているかのようだった。',item:'桃色の粘土板',itemDesc:'乾かすと甘い香りが立つ、なめらかな桃色の板だった。',trouble:'{a}は粘土の沼に腰まで沈み、引き上げられたときには足首をひねっていた。',death:'甘い粘土を口にした{v}は、その夜から高熱を出した。わずかに混じっていた毒が、静かに命を奪っていった。',report:'可食粘土の成分分析と調理法'},
{id:'coal',name:'黒い燃える石',rare:1,use:'power',sky:'大地のあちこちから、細い煙が立ちのぼっていた。地中で何かが、ずっと燻り続けているようだった。',hint:'{a}が拾った黒い石は、手のひらの中でほんのり温かかった。',detail:'{a}が火をつけると、石は青い炎を上げて長く燃え続けた。炉に入れれば、補助動力のよい燃料になりそうだった。',deep:'燃える石の層の下で、{a}は何千年も燃え続けている地下の火の川を見つけた。その熱は、星の夜を暖めていた。',item:'消えない火種',itemDesc:'黒い石の芯に、小さな炎が閉じ込められたまま揺れていた。',trouble:'{a}は石が突然はぜた火花を浴び、腕に軽いやけどを負った。',death:'地下の火の川から有毒な煙が噴き上がった。{v}は煙に巻かれて倒れ、{w}が駆けつけたときには遅かった。',report:'可燃鉱石の燃焼効率と動力転用'},
{id:'silica',name:'硝子砂の砂丘',rare:1,use:'hull',sky:'陽の当たる砂漠が、まぶしいほどに光を跳ね返していた。風が吹くたび、光の波が砂丘を渡っていった。',hint:'{a}の手のひらで、砂粒は小さなガラス玉のように透き通っていた。',detail:'{a}は砂を溶かして固め、透明で強い板を作ることに成功した。割れた観測窓の修理に使えそうだった。',deep:'砂丘の奥で、{a}は雷に打たれて固まったガラスの樹を見つけた。枝は空に向かって伸び、内側で光が迷路のように反射していた。',item:'雷のガラス樹の枝',itemDesc:'稲妻の形のまま固まった、透き通った枝だった。',trouble:'{a}は砂嵐に巻き込まれ、細かいガラス片で顔や手を傷だらけにした。',death:'砂嵐が三日続いたあと、{v}の姿は見つからなかった。{w}は光る砂丘の上で、空になった探索具だけを拾った。',report:'硝子砂を用いた観測窓の補修'},
{id:'spring',name:'温泉の湧く谷',rare:1,use:'med',sky:'山あいの谷から、白い湯気が絶え間なく立ちこめていた。谷の底は、ところどころ緑や黄色に色づいていた。',hint:'{a}が指を浸すと、湯はちょうどよい温かさだった。少し硫黄の匂いがした。',detail:'{a}は湯に、傷の治りを早める鉱物が溶けていることを突き止めた。汲んで帰れば、船の医療の助けになりそうだった。',deep:'谷の最も奥の源泉で、{a}は湯が星の深部から脈打つように湧き出していることを知った。それは、まるで星の鼓動のようだった。',item:'湯の花の結晶',itemDesc:'源泉の縁に育った、花のような形の淡い黄色の結晶だった。',trouble:'{a}は熱すぎる湯だまりに足を入れ、ふくらはぎにやけどを負った。',death:'源泉が突然噴き上がり、{v}は熱湯を浴びた。{w}の手当てもむなしく、その夜のうちに息を引き取った。',report:'温泉水の薬効と医療への応用'},
{id:'geyser',name:'雲を吐く間欠泉',rare:1,use:'o2',sky:'平原の一点から、定期的に白い柱が噴き上がっていた。柱はそのまま雲になり、星の空を流れていった。',hint:'{a}が間欠泉のそばに立つと、噴き出す霧で息がしやすく感じられた。',detail:'{a}の測定で、噴き上がる蒸気には酸素が多く含まれていると分かった。凝縮すれば、生命維持装置の補充に使えた。',deep:'間欠泉の穴の奥で、{a}は酸素を作り出す微小な鉱物の層を見つけた。この星の空は、すべてここから生まれていた。',item:'酸素を孕む白石',itemDesc:'水に沈めると、細かい泡を絶え間なく吐き出す白い小石だった。',trouble:'{a}は噴出の時刻を読み違え、吹き飛ばされて背中を強く打った。',death:'予想より早く間欠泉が噴き上がり、{v}は空高く打ち上げられた。{w}は落ちてきた体を抱きとめることしかできなかった。',report:'間欠泉の噴出周期と酸素の回収'},
{id:'deut',name:'重水素の海',rare:2,use:'power',sky:'星の半球を、重たげな灰青色の海が覆っていた。波はどこか、ゆっくりと動いているように見えた。',hint:'{a}がすくった海水は、見た目よりわずかに重かった。',detail:'{a}の分析で、海水に重水素がふつうの何百倍も含まれていると分かった。融合炉の燃料として、願ってもない宝の海だった。',deep:'海の底に潜った{a}は、重水素を濃縮し続ける巨大な泡の層を見つけた。自然が作った、星規模の精製所だった。',item:'重い水の小瓶',itemDesc:'振るとゆったり揺れる、灰青色の水を詰めた小瓶だった。',trouble:'{a}は高波にさらわれ、岸の岩に肩を打ちつけて脱臼した。',death:'採水中の小艇が重い波に呑まれた。{v}は灰青色の海に沈み、{w}だけが岸に打ち上げられた。',report:'重水素海の燃料資源としての評価'},
{id:'helium',name:'浮遊ガスの雲',rare:2,use:'power',sky:'低い空に、地面から離れて漂う金色の雲がいくつも浮かんでいた。雲は風に逆らって、同じ場所にとどまっていた。',hint:'{a}が雲に手を伸ばすと、指先がふわりと持ち上がる感じがした。',detail:'{a}は、雲が軽いガスと燃えやすい成分の混ざりものだと突き止めた。圧縮すれば、推進剤として使えそうだった。',deep:'雲の中心で、{a}はガスを吐き続ける小さな浮き石を見つけた。石たちは群れをなし、雲ごと星を巡っていた。',item:'空に浮く小石',itemDesc:'手を離すと、ゆっくり天井まで昇っていく金色の小石だった。',trouble:'{a}はガスを吸い込んで頭がくらみ、高い岩場から転げ落ちた。',death:'金色の雲に火花が飛び、空が一瞬燃え上がった。{v}はその炎の下にいて、{w}は遠くからそれを見ていた。',report:'浮遊ガス雲の採集と推進剤化'},
{id:'magnet',name:'磁鉄の尖塔',rare:2,use:'none',sky:'荒れ地に、針のように細い黒い塔が無数に立っていた。塔の周りでは、雲が渦を巻いていた。',hint:'{a}の計器の針が、塔に近づくにつれてくるくると回り始めた。',detail:'{a}は、塔が強い磁石の柱であり、星の磁場をここに集めていることを確かめた。塔の向きは、季節ごとに少しずつ変わっていた。',deep:'尖塔の配置を地図に写した{a}は、それが星の空の星座と同じ形をしていると気づいた。誰が、何のために並べたのかは分からなかった。',item:'方角を忘れた羅針',itemDesc:'尖塔の欠片で作った、いつも同じ遠い一点を指す針だった。',trouble:'{a}の工具が尖塔に吸い寄せられ、挟まれた指を痛めた。',death:'磁気の嵐が尖塔の間を走り、{v}の生命維持装置が止まった。{w}が引きずり出したとき、呼吸はもうなかった。',report:'磁鉄尖塔の配置と星の磁場'},
{id:'sulfur',name:'硫黄の花畑',rare:2,use:'med',sky:'火山のふもとに、鮮やかな黄色の斑点が一面に散らばっていた。遠目には、花が咲き乱れているようだった。',hint:'{a}が近づくと、黄色い斑点は花の形をした硫黄の結晶だった。',detail:'{a}は、結晶に熱を下げ痛みを和らげる成分が含まれていることを確かめた。精製すれば、よい薬になりそうだった。',deep:'花畑の中心で、{a}は結晶が夜ごとに少しずつ育ち、朝には開くのを見た。鉱物が、本当に咲いていたのだ。',item:'開いた硫黄の花',itemDesc:'五枚の花びらを広げた、燃えるような黄色の結晶だった。',trouble:'{a}は硫黄の煙で喉を焼き、しばらく声が出なくなった。',death:'風向きが変わり、火口の毒気が花畑を満たした。{v}は黄色い花の間に倒れ、静かに目を閉じた。',report:'硫黄結晶の薬効成分の抽出'},
{id:'copper',name:'青い銅の森',rare:2,use:'hull',sky:'丘陵が、くすんだ青緑色にびっしりと覆われていた。それは森のようにも、錆びた街のようにも見えた。',hint:'{a}が触れた木は、木ではなく枝分かれした銅の柱だった。',detail:'{a}は、銅の木が地下の鉱液を吸い上げて育っていると知った。切り出せば、船の配線と外板の修理に使えた。',deep:'森の奥で、{a}は銅の木々が根を通じて微弱な電気を送り合っているのを測った。森全体が、ひとつの回路だった。',item:'青銅の若木',itemDesc:'鉢に植えると、ゆっくり枝を伸ばし続ける小さな銅の木だった。',trouble:'{a}は銅の枝に流れていた電流に触れ、手がしびれて動かなくなった。',death:'嵐の夜、雷が銅の森に落ちた。森を伝った電流が{v}を打ち、{w}の目の前で倒れた。',report:'銅樹林の成長と船体補修材'},
{id:'sugar',name:'結晶糖の洞窟',rare:2,use:'food',sky:'岩山の斜面に、甘い匂いのする洞窟の口がいくつも開いていた。周りには小さな生き物が群がっていた。',hint:'{a}が洞窟の壁を削ると、白く透き通った甘い結晶がこぼれた。',detail:'{a}は、結晶が純度の高い糖であることを確かめた。乏しくなっていた船の食糧に、久しぶりの甘みが加わった。',deep:'洞窟の最奥で、{a}は糖の結晶が地下水と反応して、ゆっくり蜜に変わっていく泉を見つけた。泉の水面は琥珀色に光っていた。',item:'蜜の泉のしずく',itemDesc:'固まりかけた琥珀色のしずくで、ほのかに花の香りがした。',trouble:'{a}は滑りやすい結晶の床で転び、手首を折った。',death:'洞窟の天井から大きな結晶が落ちた。{v}はその下敷きになり、{w}は甘い匂いの中で泣き崩れた。',report:'結晶糖の採取と食糧備蓄'},
{id:'peat',name:'息をする泥炭',rare:2,use:'o2',sky:'湿った低地が、ゆっくりと膨らんではしぼんでいた。星そのものが呼吸しているように見えた。',hint:'{a}が泥炭を踏むと、足元からひんやりした空気が吹き出した。',detail:'{a}は、泥炭の中の微生物が昼のあいだ酸素を蓄え、夜に吐き出していることを確かめた。船内で育てれば、空気を補えそうだった。',deep:'湿地を調べ尽くした{a}は、泥炭全体がひとつの巨大な群体であると知った。その呼吸は、星の天気まで左右していた。',item:'呼吸する泥の壺',itemDesc:'蓋を開けるたび、ふわりと澄んだ空気を吐き出す小さな壺だった。',trouble:'{a}は泥炭の深みにはまり、抜け出すときに脚の筋を痛めた。',death:'夜、泥炭が一斉に息を吸い込んだ。そのそばで眠っていた{v}は、空気を奪われて目を覚まさなかった。',report:'呼吸する泥炭による空気循環'},
{id:'wind',name:'鳴き風の峡谷',rare:2,use:'power',sky:'大地を裂くように、深く長い峡谷が走っていた。谷の上空では、雲が引きちぎられるように流れていた。',hint:'{a}が峡谷に降りると、風が笛のような音を立てて吹き抜けていた。',detail:'{a}の測定で、峡谷の風は昼夜を問わず止むことがないと分かった。風車を立てれば、船の電池を満たせそうだった。',deep:'峡谷の壁に耳を当てた{a}は、風の音がひとつの旋律を繰り返していることに気づいた。それは何千年も同じ歌だった。',item:'風を記した石板',itemDesc:'風に削られた溝が、楽譜のように並んだ平たい石だった。',trouble:'{a}は突風にあおられ、峡谷の岩壁に体を打ちつけた。',death:'峡谷を吹き抜けた突風が、{v}を崖の向こうへ連れ去った。{w}の耳には、風の歌だけが残った。',report:'峡谷風力による充電計画'},
{id:'sing',name:'歌う結晶',rare:3,use:'none',sky:'山脈の一角が、虹色の光をまだらに放っていた。通信機は、その方角からかすかな音を拾った。',hint:'{a}が近づくと、透明な結晶が風もないのに澄んだ音を響かせていた。',detail:'{a}は、結晶が星の振動を受けて歌っていると知った。結晶ごとに音の高さが違い、群れで和音を奏でていた。',deep:'{a}が結晶の歌を記録して逆再生すると、それは船の通信と同じ周波数の、誰かの呼びかけだった。',item:'鳴りやまない結晶',itemDesc:'手のひらで、絶えず小さな子守歌を口ずさむ透明な結晶だった。',trouble:'{a}は結晶の高い音を長く聞きすぎ、耳鳴りと目まいに倒れた。',death:'結晶の歌が突然ひとつの高い音に重なった。その響きの中心にいた{v}は、静かに崩れ落ちた。',report:'歌う結晶の音響と周波数の記録'},
{id:'livemetal',name:'生きた金属',rare:3,use:'hull',sky:'銀色の大地が、ところどころ波打つように動いていた。光の加減で、模様がゆっくり変わっていった。',hint:'{a}が置いた工具の上を、銀色の液体がそっとなぞって離れていった。',detail:'{a}は、金属が傷ついた場所に自ら集まって形を戻すことを確かめた。船体に塗れば、ひびを自分で埋めてくれそうだった。',deep:'{a}が金属に文字を刻むと、翌朝、その隣に見知らぬ記号が刻み返されていた。金属は、学んでいた。',item:'懐く銀の滴',itemDesc:'持ち主の手の温もりを覚え、そっと指に絡みついてくる銀色の滴だった。',trouble:'{a}の腕に銀の金属が絡みつき、引き剥がすときに皮膚を傷めた。',death:'生きた金属が{v}の装備に入り込み、内側から固まった。{w}が外したとき、呼吸の音は消えていた。',report:'自己修復金属の船体への応用'},
{id:'mist',name:'癒しの霧',rare:3,use:'med',sky:'森の谷あいに、淡い緑色の霧が一日中たなびいていた。霧は夜になると、ほのかに光った。',hint:'{a}が霧の中を歩くと、古傷の痛みがふっと和らいだ。',detail:'{a}は、霧の粒が体の修復を促す物質を運んでいると突き止めた。集めて凝縮すれば、船の薬が作れた。',deep:'霧の湧き出す泉で、{a}は霧が傷ついた生き物のもとへ自ら流れていくのを見た。霧は、星の看護人だった。',item:'霧を封じた瓶',itemDesc:'中で緑の霧がゆっくり渦を巻き、手に持つと気持ちが落ち着く瓶だった。',trouble:'{a}は霧の中で方向を見失い、さまよううちに崖から足を踏み外した。',death:'霧に包まれた{v}は、穏やかな顔で眠りについた。癒しの霧は、深すぎる眠りまで運んでしまった。',report:'治癒の霧の成分と医療利用'},
{id:'lightstone',name:'光を溜める石',rare:3,use:'power',sky:'夜側の大地に、星空を写したような光の点が無数に灯っていた。光は夜明けとともに消えていった。',hint:'{a}が拾った石は、昼の光を吸い込んで、日陰でぼんやり輝いていた。',detail:'{a}は、石が光をほとんど損なわずに蓄え、ゆっくり放つことを確かめた。並べれば、船の非常電源になりそうだった。',deep:'地中深くで、{a}は何万年も前の陽光をまだ抱いている巨大な石を見つけた。その光は、今とは違う色の太陽のものだった。',item:'古い陽の欠片',itemDesc:'遠い昔の太陽の光を、今も柔らかく放ち続ける石の欠片だった。',trouble:'{a}は石が一度に放った光に目を焼かれ、しばらく包帯を巻いて過ごした。',death:'光を溜めすぎた石が、夜明け前に砕けて熱を放った。そばにいた{v}は、その光の中で倒れた。',report:'蓄光石を用いた非常電源の設計'},
{id:'seed',name:'眠る種子の層',rare:3,use:'food',sky:'乾いた大地に、縞模様のような茶色と金色の地層が広がっていた。どこにも緑は見えなかった。',hint:'{a}が地層を崩すと、中から小さな種がこぼれ出た。どれも固い殻に包まれていた。',detail:'{a}が水を与えると、種は数日で芽を出し、食べられる実をつけた。船の菜園に新しい作物が加わった。',deep:'地層の最下層で、{a}は見たこともない種を見つけた。その殻には、星の外から来たことを示す焦げ跡が残っていた。',item:'名もない種',itemDesc:'どんな植物になるのか誰にも分からない、星の外から来た種だった。',trouble:'{a}は種の殻が弾けた破片を浴び、目を傷めた。',death:'{v}が試しに食べた実には、眠りを誘う毒があった。{w}がどれほど呼んでも、目を覚ますことはなかった。',report:'休眠種子の発芽と船内栽培'},
{id:'mirror',name:'鏡の湖',rare:3,use:'none',sky:'平原の中に、完全に空を映す銀色の湖があった。湖面には、波ひとつ立っていなかった。',hint:'{a}が湖面をのぞくと、映った自分がわずかに遅れて動いた。',detail:'{a}は、湖が光を一瞬とどめてから返していることを確かめた。湖面には、少し前の景色が映り続けていた。',deep:'湖を見続けた{a}は、ある夜、湖面にこの船が漂流を始めた日の景色を見た。湖は、見る者の過去を映していた。',item:'映り込みの欠片',itemDesc:'のぞくたびに、少しだけ昔の自分の顔が映る銀色の破片だった。',trouble:'{a}は湖面に見入るうちに時間を忘れ、ひどく体を冷やして寝込んだ。',death:'{v}は湖に映った懐かしい誰かに手を伸ばし、そのまま銀色の水に沈んでいった。',report:'鏡の湖における光の遅延現象'},
{id:'bubble',name:'呼吸する泡石',rare:3,use:'o2',sky:'海岸線に沿って、白い泡のような岩が積み重なっていた。岩はときおり、大きな泡をはじけさせた。',hint:'{a}が泡石を割ると、中から澄んだ空気がふわりと漏れ出た。',detail:'{a}は、泡石が周りの二酸化炭素を吸って酸素を吐くことを突き止めた。船内に置けば、空気を浄化してくれた。',deep:'{a}は、泡石の中に小さな生き物が暮らし、石を家として育てていることを知った。石と生き物は、互いに息を分け合っていた。',item:'息づく泡石',itemDesc:'手のひらで、規則正しく膨らんだり縮んだりする白い石だった。',trouble:'{a}は泡石の崩れた山に巻き込まれ、肋骨にひびが入った。',death:'泡石の洞で、空気が突然すべて吸い上げられた。{v}は息を求めて倒れ、{w}の助けは間に合わなかった。',report:'泡石による船内空気の浄化'},
{id:'amber',name:'時を止める琥珀',rare:4,use:'med',sky:'森の跡地に、夕陽のような色の大きな塊がいくつも横たわっていた。周りの景色だけが、少しかすんで見えた。',hint:'{a}が琥珀に手を当てると、腕時計の針が一瞬止まった。',detail:'{a}は、琥珀の中では時間がほとんど進まないことを確かめた。重い怪我人を包めば、治療の時間を稼げそうだった。',deep:'琥珀の一つの中で、{a}は飛び立とうとする鳥を見た。その羽は、{a}の見ている前でほんの少しだけ動いていた。',item:'止まった時の粒',itemDesc:'中の小さな水滴が、落ちる途中のまま浮かんでいる琥珀の粒だった。',trouble:'{a}は琥珀に指を触れたまま動けなくなり、離れたときには腕がしびれきっていた。',death:'{v}は琥珀の割れ目に入り込み、時の流れから取り残された。{w}には、その姿がいつまでも見えていた。',report:'時間遅延琥珀の医療応用'},
{id:'gravity',name:'重さのない鉱石',rare:4,use:'hull',sky:'大地の上に、岩の島がいくつも浮かんでいた。島からは、細い滝が空中にこぼれていた。',hint:'{a}が浮き島の岩を手に取ると、羽のように軽かった。',detail:'{a}は、鉱石が重力を打ち消す性質をもつことを確かめた。船体に組み込めば、軽く丈夫な装甲になりそうだった。',deep:'浮き島の芯で、{a}は重さが逆向きにはたらく鉱脈を見つけた。それは、船を空へ押し上げる力さえ秘めていた。',item:'浮かぶ石の首飾り',itemDesc:'身につけると体がわずかに軽くなる、灰色の石を連ねた首飾りだった。',trouble:'{a}は浮き島から足を滑らせ、ゆっくり落ちたものの足首を痛めた。',death:'重さのない鉱石を抱えたまま、{v}の体は空へ昇っていった。{w}は、小さくなる影を見送るしかなかった。',report:'反重力鉱石と軽量装甲の試作'},
{id:'memwater',name:'記憶する水',rare:4,use:'none',sky:'大地に、無数の小さな池が点々と散らばっていた。どの池も、少しずつ違う色をしていた。',hint:'{a}が池の水に触れると、知らない景色が一瞬まぶたに浮かんだ。',detail:'{a}は、水が触れた者の記憶を少しずつ写し取っていることを知った。池ごとに、違う誰かの思い出が眠っていた。',deep:'最も古い池で、{a}はこの星に暮らしていた誰かの、最後の一日の記憶に触れた。その人々は、星の空を見上げて誰かを待っていた。',item:'思い出の雫',itemDesc:'手に取ると、見知らぬ誰かの穏やかな夕暮れが心に浮かぶ雫だった。',trouble:'{a}は他人の記憶に深く入り込みすぎ、数日のあいだ自分の名前を思い出せなかった。',death:'{v}は池に映る記憶に呑まれ、自分の記憶を水に残して帰らなかった。{w}は今も、その池をのぞけば会える気がしていた。',report:'記憶を保持する水の性質'},
{id:'starshard',name:'星の欠片',rare:4,use:'power',sky:'大地の一点に、巨大なクレーターが口を開けていた。その底では、白い光が脈打っていた。',hint:'{a}がクレーターの縁に立つと、計器がいっせいに振り切れた。',detail:'{a}は、底に眠るのが遠い恒星から飛んできた物質だと突き止めた。わずかな量で、船の炉を何年も動かせる力があった。',deep:'欠片の中心で、{a}はまだ小さな核融合が続いているのを見た。それは、生まれそこねた星の赤子だった。',item:'燃える星屑',itemDesc:'容器の中で白く瞬き続ける、星の内側の小さなかけらだった。',trouble:'{a}は欠片の放つ熱と光を浴びすぎ、肌がひどくただれた。',death:'欠片の光が強まった瞬間、{v}はそのそばにいた。{w}が目を開けたとき、そこには白い灰だけが残っていた。',report:'恒星由来物質による炉心の再起動'},
{id:'heart',name:'星の心臓',rare:5,use:'power',sky:'星全体が、一定の間隔でほのかに明るくなっては暗くなっていた。まるで脈を打つように。',hint:'{a}が地面に手を当てると、ゆっくりとした鼓動が伝わってきた。',detail:'{a}は、星の中心に巨大なエネルギーの塊があり、それが鼓動のように力を送り出していると知った。その一滴で、船はどこへでも行けそうだった。',deep:'地の底で心臓にたどり着いた{a}は、それがまだ若い星の意識であることを感じた。心臓は、一行がやって来たことを喜んでいた。',item:'鼓動のかけら',itemDesc:'星の心臓から分けてもらった、温かく脈打つ赤い石だった。',trouble:'{a}は鼓動の衝撃波に打たれ、しばらく胸の痛みが取れなかった。',death:'星の心臓が大きく打った瞬間、{v}の鼓動はそれに重なり、そして止まった。{w}は、星の鼓動だけが続くのを聞いていた。',report:'星の心臓とその無尽のエネルギー'},
{id:'dreamsand',name:'夢見る砂',rare:5,use:'none',sky:'砂漠の砂が、昼も夜も色を変えながら流れていた。砂の模様は、どれ一つとして同じではなかった。',hint:'{a}が砂の上で眠ると、見たことのない街の夢を見た。',detail:'{a}は、砂が眠る者に星の記憶を夢として見せていることを確かめた。夢の中の街は、毎晩少しずつ姿を変えていた。',deep:'夢の街の中心で、{a}は自分たちの船がこの星に辿り着く様子を描いた壁画を見た。砂は、ずっと前からこの日を知っていた。',item:'夢の砂時計',itemDesc:'落ちる砂の中に、見る者がいつか見る夢がちらりと映る砂時計だった。',trouble:'{a}は夢から何日も覚めず、目覚めたときにはすっかりやつれていた。',death:'{v}は夢見る砂の上で眠り、そのまま夢の街の住人になった。{w}は、穏やかな寝顔をいつまでも見つめていた。',report:'夢見る砂と星の記憶の記録'},
{id:'nectar',name:'不老の蜜',rare:5,use:'food',sky:'大陸の奥に、金色に光る湖があった。その周りだけ、季節がずっと春のままだった。',hint:'{a}が湖の縁に指を浸すと、金色のとろりとした蜜がまとわりついた。',detail:'{a}は、蜜がわずかな量で一日分の栄養を満たすことを確かめた。蓄えれば、船の飢えはもう心配なかった。',deep:'湖の周りの古い木々を調べた{a}は、それらが何万年も若いまま生きていると知った。蜜は、時に抗う力を秘めていた。',item:'金の蜜の小壺',itemDesc:'ひと舐めで疲れが消える、決して減らないといわれる金色の蜜の壺だった。',trouble:'{a}は蜜の湖に足を取られて抜け出せず、引き上げられるまでに体力を使い果たした。',death:'{v}は不老の蜜を口にしすぎ、深い眠りから覚めなかった。若いままの寝顔を、{w}は長いあいだ見守った。',report:'不老の蜜の栄養価と長寿の謎'}
];
})();
});
;
/* ==== js/ship-life.js ==== */
HK.Load.def(245,'js/ship-life.js',function(){
(function(){
'use strict';
var HK=window.HK,SH=HK.SHIP=HK.SHIP||{};
SH.LIFE=[
{id:'drifter',name:'浮遊クラゲ',rare:2,kind:'friendly',
look:'{a}は、薄紫の空を漂う半透明の傘をいくつも見つけた。傘の縁からは細い光の糸が垂れ、風もないのにゆっくりと揺れていた。',
habit:'{a}の観察で、浮遊クラゲは体内に軽い気体を溜めて浮いているとわかった。夜になると群れで集まり、互いの光を明滅させて何かを伝え合っていた。',
deep:'{a}は、クラゲたちの明滅が星の地図になっていることに気づいた。クラゲたちは何世代もかけて、空の星の位置を光で記憶し、受け継いでいたのだ。',
good:'{a}が手持ちの灯りをゆっくり点滅させると、一匹のクラゲが降りてきて腕にふわりと触れた。冷たく、どこか懐かしい感触だった。',
bad:'{a}が近づきすぎた瞬間、驚いたクラゲが光の糸を振り下ろした。痺れが走り、{a}はしばらく指先の感覚を失った。',
death:'{v}は、密集したクラゲの群れの中で無数の光の糸に絡め取られた。{w}が駆けつけたとき、{v}はもう動かなかった。',
item:'クラゲの浮き袋',itemDesc:'中に軽い気体を閉じ込めたままの、手のひらほどの透明な袋。',
report:'空を泳ぐ傘についての覚え書き'},
{id:'lantern_otter',name:'灯り尾のカワウソ',rare:1,kind:'friendly',
look:'{a}は、水辺を跳ねまわる小さな獣を見つけた。長い尾の先が橙色に灯り、水面にちらちらと光の輪を落としていた。',
habit:'灯り尾のカワウソは、尾の光で水中の小魚を誘い寄せて捕まえていた。{a}は、カワウソたちが獲物を仲間と分け合う姿を何度も目にした。',
deep:'{a}は、尾の光が寿命とともに少しずつ暗くなることを知った。年老いた個体は群れの若者に光る苔を運ばせ、灯りを分けてもらっていた。',
good:'{a}が干し肉の切れ端を差し出すと、カワウソは尾を揺らして寄ってきた。食べ終えると、礼のように小石をひとつ置いていった。',
bad:'{a}が尾に触れようとした途端、カワウソは鋭い歯で手に噛みついた。小さな傷だったが、しばらく熱を持って腫れた。',
death:'{v}はカワウソを追って水辺に踏み込み、ぬかるみに足を取られて深みへ沈んだ。{w}の伸ばした手は届かなかった。',
item:'灯り尾の小石',itemDesc:'カワウソが置いていった、うっすらと橙色に光る丸い小石。',
report:'水辺の灯火と小さな狩人'},
{id:'glass_bird',name:'硝子の鳥',rare:3,kind:'friendly',
look:'{a}は、陽を受けて虹色に輝く鳥の群れを見上げた。羽も嘴も透き通っていて、羽ばたくたびに鈴のような音がした。',
habit:'硝子の鳥は鉱物の砂を食べ、体内でそれを溶かして羽を作っていた。{a}は、鳥たちが崖の結晶に巣をかけ、雛に砂を口移しする様子を記録した。',
deep:'{a}は、鳥たちの羽音が実は言葉だと気づいた。羽の厚みを変えて音程を作り、遠く離れた群れと歌で会話していたのだ。',
good:'{a}が静かに座っていると、一羽の硝子の鳥が肩にとまった。透明な羽ごしに見る空は、虹の帯で彩られていた。',
bad:'{a}が巣に近づくと、群れが一斉に急降下してきた。硝子の嘴がかすめ、{a}の頬と腕に細い切り傷が走った。',
death:'{v}は崖の巣を覗こうとして、怒った鳥たちに囲まれた。足を踏み外した{v}は、結晶の谷底へと落ちていった。',
item:'硝子の羽根',itemDesc:'光にかざすと内側で虹が揺れる、鳥が落とした透明な羽根。',
report:'歌う硝子の群れ'},
{id:'echo_deer',name:'木霊鹿',rare:2,kind:'friendly',
look:'{a}は、森の奥で枝のような角を持つ細身の獣と目が合った。角の先には小さな穴がいくつも空き、風が通るたびに低く鳴った。',
habit:'木霊鹿は角の音を反響させて、森の中の地形を探っていた。{a}は、群れが音で互いの位置を確かめながら移動することを突き止めた。',
deep:'{a}は、鹿たちが船の機関音を真似していることに気づいた。鹿たちは聞いたことのない音を群れ全体で覚え、森の新しい住人として受け入れようとしていた。',
good:'{a}が口笛で角の音を真似ると、木霊鹿は首をかしげて同じ音を返してきた。しばらく、森に二つの音色が響き合った。',
bad:'{a}の足音に驚いた木霊鹿が後ろ脚で蹴り上げた。{a}は胸を打たれて倒れ、しばらく息がうまく吸えなかった。',
death:'{v}は、暴走した木霊鹿の群れの進路に立ってしまった。角の音が鳴り止んだあと、{w}は倒れた{v}を見つけた。',
item:'木霊鹿の落とし角',itemDesc:'吹けば森の奥まで届く低い音が鳴る、生え替わりで落ちた角。',
report:'音で森を見る獣'},
{id:'mimic_pup',name:'真似っ子',rare:1,kind:'friendly',
look:'{a}の足元に、丸い毛玉のような生き物が転がってきた。つぶらな目が六つあり、{a}が首をかしげると同じように首をかしげた。',
habit:'真似っ子は、目の前の生き物の動きをそっくり真似て敵意がないことを示していた。{a}は、毛玉たちが群れの中でも互いの真似をして遊ぶのを見た。',
deep:'{a}は、真似っ子が真似た相手の感情まで写し取っていることに気づいた。悲しむ者のそばでは、毛玉たちもまた静かに震えていた。',
good:'{a}が手を振ると、真似っ子は短い前脚を振り返した。そのまま後をついてきて、船の入口まで見送ってくれた。',
bad:'{a}が抱き上げようとすると、真似っ子は毛を逆立てて細い棘を飛ばした。手のひらに刺さった棘を抜くのに、{a}は半日かかった。',
death:'{v}は真似っ子を追って岩場の割れ目に入り込み、崩れた岩の下敷きになった。真似っ子たちは、いつまでもその場で震えていた。',
item:'真似っ子の抜け毛',itemDesc:'持ち主の気分に合わせて色が変わる、ふわふわの毛の束。',
report:'真似をする毛玉の記録'},
{id:'star_whale',name:'星鯨の幼体',rare:5,kind:'friendly',
look:'{a}は、低い空をゆったりと泳ぐ巨大な影を見上げた。背中には星屑のような斑点が散り、腹からは柔らかな歌が降ってきた。',
habit:'星鯨の幼体は、星の上層大気で光を浴びて育っていた。{a}は、幼体がある程度大きくなると宇宙へ飛び立つ準備を始めることを知った。',
deep:'{a}は、星鯨が宇宙を渡る生き物だと確信した。この星は親鯨たちが子を預ける揺りかごで、幼体はいずれ星の海へ旅立つのだった。',
good:'{a}が信号灯を灯すと、幼体はゆっくりと高度を下げてきた。大きな瞳が{a}を映し、腹の底に響く歌をひとつ贈ってくれた。',
bad:'幼体が身をひるがえした瞬間、巻き起こった風が{a}を吹き飛ばした。地面に叩きつけられた{a}は、肩を痛めて船へ戻った。',
death:'{v}は、降下してきた星鯨の幼体の尾びれに打たれた。悪意はなかったのだろう。幼体は悲しげな歌を残して空へ昇っていった。',
item:'星鯨の鱗片',itemDesc:'内側に小さな星空を閉じ込めたような、青黒く光る鱗のかけら。',
report:'星の海を渡る子らについて'},
{id:'bubble_snail',name:'泡吹き貝',rare:1,kind:'friendly',
look:'{a}は、岩の上でしゃぼん玉を吹く小さな巻貝を見つけた。泡は七色に光り、ぷかぷかと漂っては静かに弾けた。',
habit:'泡吹き貝は、泡に香りを閉じ込めて仲間を呼んでいた。{a}は、泡が弾けた場所に別の貝がゆっくり集まってくるのを確かめた。',
deep:'{a}は、泡の中に微量の酸素が含まれていることを突き止めた。この貝たちは、何万年もかけて星の大気を少しずつ作り変えてきたのだ。',
good:'{a}がそっと指を差し出すと、泡吹き貝は殻から顔を出し、小さな泡をひとつ吹きかけた。甘い花のような香りが広がった。',
bad:'{a}が貝を持ち上げると、泡吹き貝は刺激の強い泡を吐き出した。目に入った泡のせいで、{a}は一日じゅう涙が止まらなかった。',
death:'{v}は、泡が無数に溜まった窪地で足を滑らせた。泡に包まれて息ができず、{w}が引き上げたときには遅かった。',
item:'泡吹き貝の空殻',itemDesc:'耳に当てると、かすかに泡の弾ける音が聞こえる巻貝の殻。',
report:'大気を吹く小さな貝'},
{id:'sand_mind',name:'群体知性の砂',rare:4,kind:'neutral',
look:'{a}は、風もないのに波打つ砂の原を見つけた。砂粒はひとつひとつが微細な生き物で、ときおり幾何学的な模様を描いては崩した。',
habit:'群体知性の砂は、陽の向きに合わせて全体で形を変え、熱を集めていた。{a}は、砂が障害物を避けて流れる様子に明確な判断を感じた。',
deep:'{a}は、砂の描く模様が計算式だと気づいた。群体は星全体の気候を予測し、数百年先の嵐から逃れる道筋を静かに解き続けていた。',
good:'{a}が砂の上に図形を描くと、群体はしばらく沈黙したのち、その図形を正確に写し返した。{a}は手早く記録を取った。',
bad:'{a}が採取用の容器を差し込むと、砂が一斉に流れ込んで足首まで呑み込んだ。抜け出したとき、{a}の脚は擦り傷だらけだった。',
death:'{v}は砂の原を横切る途中、足元の群体が渦を巻いて崩れ落ちた。砂は何事もなかったように平らに戻り、{v}の姿は消えていた。',
item:'考える砂の小瓶',itemDesc:'瓶を傾けるたびに、中の砂が違う模様を描き直す小瓶。',
report:'思考する砂丘の観測'},
{id:'stone_turtle',name:'岩甲羅',rare:1,kind:'neutral',
look:'{a}が岩だと思って腰かけたものが、ゆっくりと動き出した。苔むした甲羅の下から、眠たげな目がこちらを見ていた。',
habit:'岩甲羅は、一日に数歩しか歩かず、甲羅に生えた苔から養分を得ていた。{a}は、甲羅の上に小さな生き物が何種類も暮らしているのを見つけた。',
deep:'{a}は甲羅の年輪を調べ、この個体が千年以上生きていると知った。岩甲羅は、星の地形の変化をその身に刻む生きた記録だった。',
good:'{a}が甲羅の苔を少し分けてもらっても、岩甲羅は気にも留めなかった。ゆっくりと瞬きをして、また眠りに戻っていった。',
bad:'{a}が甲羅を叩くと、岩甲羅は首を引っこめた拍子に{a}の手を挟んだ。指を引き抜いたとき、爪が一枚割れていた。',
death:'{v}が斜面の下で調べものをしていたとき、寝返りを打った岩甲羅が転がり落ちてきた。{w}が叫んだときにはもう遅かった。',
item:'甲羅の苔',itemDesc:'千年分の時間を吸ったような、深い緑色のふかふかした苔。',
report:'歩く岩と千年の記録'},
{id:'mirror_beast',name:'鏡の獣',rare:3,kind:'neutral',
look:'{a}は、平原にたたずむ銀色の獣に気づいた。毛並みは磨いた鏡のようで、そこに映った自分の姿が少し遅れて動いた。',
habit:'鏡の獣は、体表で光を反射して周囲に溶け込み、外敵から身を隠していた。{a}は、獣たちが群れで並ぶと、まるで景色に穴が空いたように見えると記した。',
deep:'{a}は、獣の体に映る像が実際より数秒先の景色であることに気づいた。鏡の獣は、ほんの少し先の未来を映して危険を避けていたのだ。',
good:'{a}が距離を保って座っていると、鏡の獣はこちらを一瞥しただけで去っていった。体に映った{a}の像は、なぜか微笑んでいた。',
bad:'{a}が獣の正面に立つと、強い反射光が目を焼いた。{a}はしばらく視界が白く霞み、手探りで船へ戻った。',
death:'{v}は、鏡の獣の群れに映る幻の道を本物と思い込み、崖の縁を踏み越えた。{w}の目には、獣たちの体に落ちていく{v}が映っていた。',
item:'鏡の毛',itemDesc:'覗きこむと、自分の姿がほんの一瞬早く動いて見える銀色の毛。',
report:'先を映す鏡の獣'},
{id:'cloud_grazer',name:'雲食み',rare:2,kind:'neutral',
look:'{a}は、山の稜線に沿って漂う、綿のように膨らんだ生き物を見た。長い口吻を伸ばし、低く垂れた雲をゆっくり吸いこんでいた。',
habit:'雲食みは雲の水分と微生物を食べ、満腹になると重くなって谷へ降りていった。{a}は、雲食みたちの通り道だけ雨が降らないことに気づいた。',
deep:'{a}は、雲食みが谷で水を吐き出し、湖を作っていることを突き止めた。この星の川と湖は、ほとんどが雲食みたちの吐いた水でできていた。',
good:'{a}が見守るなか、雲食みは何の関心も示さずにすぐ頭上を通り過ぎた。落ちてきた一滴の水は、驚くほど澄んでいた。',
bad:'{a}の頭上で雲食みが急に水を吐き出し、{a}は濁流に押し流された。岩にぶつかった膝を、しばらく引きずって歩いた。',
death:'{v}は谷底で計測をしていたとき、満腹の雲食みが一斉に水を吐き出した。{w}は高台から、水に呑まれる{v}を見ていることしかできなかった。',
item:'雲の結晶',itemDesc:'雲食みの口元に固まっていた、ひんやりと湿った白い結晶。',
report:'雲を食べる者たち'},
{id:'clock_beetle',name:'時計虫',rare:3,kind:'neutral',
look:'{a}は、真鍮色の甲虫が地面をかちかちと音を立てて歩くのを見つけた。背中には文字盤のような同心円の模様があった。',
habit:'時計虫は、毎日決まった時刻に一斉に羽を鳴らしていた。{a}は、その間隔が星の自転周期と寸分違わず一致していることを確かめた。',
deep:'{a}は、時計虫の羽音が星の内部の振動と共鳴していることを発見した。虫たちは地殻のずれを測り、地震の前には一斉に高台へ移っていた。',
good:'{a}がじっと待っていると、時計虫たちは正確な時刻に一斉に羽を鳴らした。{a}はその音を船の時計合わせに使った。',
bad:'{a}が群れの中に足を踏み入れると、時計虫が一斉に硬い殻で体当たりしてきた。{a}は全身にあざを作って退いた。',
death:'{v}は、時計虫が一斉に去った谷に残って測定を続けた。その直後に起きた地揺れで、{v}は崩れた岩場に呑まれた。',
item:'時計虫の殻',itemDesc:'背の同心円が、持っているとかすかに時を刻むように震える殻。',
report:'星の鼓動を測る虫'},
{id:'hollow_giant',name:'うつろ巨人',rare:4,kind:'neutral',
look:'{a}は、地平線をまたぐように歩く巨大な影を見た。人の形にも見えたが、胴の中は空洞で、向こうの空が透けていた。',
habit:'うつろ巨人は、何日もかけて同じ道をゆっくりと往復していた。{a}は、巨人の通った後の土が耕され、草が芽吹いていることに気づいた。',
deep:'{a}は、巨人の空洞の胴の中に、小さな生態系が丸ごと収まっていることを知った。巨人は、移ろう季節に合わせて森そのものを運んでいたのだ。',
good:'{a}が巨人の足元で観察を続けても、巨人は一度も足を止めなかった。去り際に落ちてきた種を、{a}は大切に拾い上げた。',
bad:'巨人の一歩が地面を揺らし、{a}は宙に放り出された。着地のときに足首をひねり、{a}は仲間の肩を借りて戻った。',
death:'{v}は巨人の足跡を調べている最中、引き返してきた巨人の次の一歩に気づかなかった。地響きが去ったあと、{w}はその場に立ち尽くした。',
item:'巨人の運ぶ種',itemDesc:'うつろ巨人の胴から落ちた、拳ほどもある重たい木の実。',
report:'森を運ぶ巨人'},
{id:'ribbon_eel',name:'光帯ウナギ',rare:2,kind:'neutral',
look:'{a}は、湖の底で揺れる幾筋もの光の帯を見つけた。それは長いウナギの群れで、体の側面が淡い青に光っていた。',
habit:'光帯ウナギは、湖底の温かい噴き出し口のまわりで暮らしていた。{a}は、ウナギたちが光の強さで縄張りを主張し合っているのを観察した。',
deep:'{a}は、ウナギの光が湖底の植物を育てていることを突き止めた。光の届かない深みで、ウナギたちは自ら太陽の代わりを務めていた。',
good:'{a}が静かに水に手を浸すと、光帯ウナギは無関心に指の間をすり抜けていった。その一瞬、水中が青い光で満たされた。',
bad:'{a}がウナギに触れた瞬間、体を走る光が電撃に変わった。{a}は腕を痺れさせたまま、慌てて水から這い上がった。',
death:'{v}は湖に潜って採取をしていたとき、ウナギの群れが一斉に放った電撃を浴びた。{w}が引き上げた体は、まだ淡く青く光っていた。',
item:'光帯ウナギの皮',itemDesc:'乾いてもなお、暗がりで青く脈打つように光る細長い皮。',
report:'湖底の小さな太陽'},
{id:'thorn_wolf',name:'棘狼',rare:2,kind:'hostile',
look:'{a}は、岩陰からこちらを窺う灰色の獣たちに気づいた。背中には鋭い棘が逆立ち、低いうなり声が四方から聞こえた。',
habit:'棘狼は群れで獲物を追い込み、棘を飛ばして弱らせてから仕留めていた。{a}は、狼たちが風下から音もなく近づく狩りの手順を記録した。',
deep:'{a}は、棘狼の棘に毒がないことを知って驚いた。棘は群れの仲間を見分ける印で、一本一本に個体ごとの違う模様が刻まれていた。',
good:'{a}は風下を避けて身を潜め、群れの狩りを最後まで見届けた。棘狼たちは{a}に気づかないまま、獲物を引いて去っていった。',
bad:'{a}の匂いを嗅ぎつけた棘狼が、背の棘を一斉に放った。何本かが腕と脚に刺さり、{a}は血をにじませながら船へ逃げ帰った。',
death:'{v}は、夜の探索中に棘狼の群れに囲まれた。{w}が灯りを掲げて駆けつけたとき、群れはすでに闇へ消えていた。',
item:'棘狼の抜け棘',itemDesc:'根元に細かな模様が刻まれた、硬く鋭い灰色の棘。',
report:'棘を持つ狩人の群れ'},
{id:'shadow_mantis',name:'影蟷螂',rare:3,kind:'hostile',
look:'{a}は、木の幹に張りついた影が、ふいに形を変えるのを見た。それは細長い鎌を持つ黒い虫で、光を吸いこむように暗かった。',
habit:'影蟷螂は、物陰と見分けがつかないほど体色を沈め、通りかかる獲物を待ち伏せていた。{a}は、蟷螂たちが光の強い昼間には決して動かないことに気づいた。',
deep:'{a}は、影蟷螂の体が本当に光を吸収し、それを蓄えていることを知った。夜になると、蟷螂たちは蓄えた光で互いを呼び合っていた。',
good:'{a}は強い照明を掲げたまま、影蟷螂の巣を慎重に観察した。光の中で動けない虫たちから、{a}は脱皮殻を一つ持ち帰った。',
bad:'{a}が日陰に足を踏み入れたとたん、影の中から鎌が振り下ろされた。肩を浅く裂かれた{a}は、日なたへ転がり出て難を逃れた。',
death:'{v}は、夕暮れの森で影蟷螂の待ち伏せに遭った。{w}が影の中を照らしたとき、{v}はもう息をしていなかった。',
item:'影蟷螂の脱皮殻',itemDesc:'光を当てても黒いままの、影をそのまま固めたような殻。',
report:'影に潜む鎌'},
{id:'storm_ray',name:'雷エイ',rare:3,kind:'hostile',
look:'{a}は、嵐雲の下を滑空する平たい影の群れを見た。翼のような胸びれの縁で、絶えず青白い火花が弾けていた。',
habit:'雷エイは嵐の電気を体に溜め、地上の獲物に雷を落として狩りをしていた。{a}は、エイたちが嵐の前触れとともに現れることを突き止めた。',
deep:'{a}は、雷エイが嵐を呼んでいることに気づいた。群れで大気を攪拌し、雲を集めて、自分たちの狩り場を作り出していたのだ。',
good:'{a}は避雷用の杭を立てて身を伏せ、嵐の中の狩りを観察した。雷エイが去ったあと、杭の先には帯電した鱗が残っていた。',
bad:'{a}が高台に立った瞬間、雷エイが放った稲妻が近くの岩を砕いた。{a}は衝撃で吹き飛ばされ、腕にやけどを負った。',
death:'{v}は嵐の中、開けた平原で雷エイの群れに狙われた。閃光が走ったあと、{w}の耳には雷鳴だけが残った。',
item:'帯電した鱗',itemDesc:'触れるとぱちりと静電気が走る、青白く光る平たい鱗。',
report:'嵐を呼ぶ翼'},
{id:'maw_worm',name:'地喰い大蚯蚓',rare:4,kind:'hostile',
look:'{a}は、地面に残された大きな円い穴を見つけた。穴の縁は内側へなめらかに崩れ、奥からは湿った土の匂いが立ちのぼっていた。',
habit:'地喰い大蚯蚓は、地中深くを泳ぐように進み、地表の振動を頼りに獲物を襲っていた。{a}は、それが柔らかい土の多い場所を好むことを確かめた。',
deep:'{a}は、大蚯蚓が通った跡に鉱脈が集まっていることに気づいた。大蚯蚓は岩を食べて体内で金属を濾し分け、地中に鉱石の道を残していた。',
good:'{a}は硬い岩盤の上から動かず、大蚯蚓が地表に顔を出すのを待った。巨大な口が閉じるまでの一瞬を、{a}は記録に収めた。',
bad:'{a}の足元の地面が突然盛り上がり、大蚯蚓が飛び出してきた。{a}は寸前で横に転がったが、跳ね飛ばされて肋骨を痛めた。',
death:'{v}が柔らかい土の上で掘削をしていたとき、地面ごと大蚯蚓に呑みこまれた。{w}の前には、ぽっかりと開いた穴だけが残った。',
item:'蚯蚓の濾し石',itemDesc:'大蚯蚓の通り道で拾った、金属の粒がぎっしり詰まった石。',
report:'地を呑む者の通り道'},
{id:'needle_swarm',name:'針羽虫の群れ',rare:1,kind:'hostile',
look:'{a}は、遠くで黒い霞のようなものが渦巻いているのを見た。近づくにつれ、それが無数の小さな羽虫の群れだとわかった。',
habit:'針羽虫は、体温の高い生き物に群がって血を吸っていた。{a}は、群れが冷たい岩場や水辺を避けることに気づき、それを記録した。',
deep:'{a}は、針羽虫の群れ全体がひとつの意思で動いていることを突き止めた。群れは、仲間を失うほど慎重になり、狩り方を変えていた。',
good:'{a}は冷却材を体に塗って体温を下げ、群れの真横を通り抜けた。針羽虫は{a}に見向きもせず、渦を巻いたまま去っていった。',
bad:'{a}は針羽虫の群れに襲われ、顔と腕を何十か所も刺された。腫れが引くまで、{a}は三日間ほとんど目を開けられなかった。',
death:'{v}は、逃げ場のない窪地で針羽虫の大群に包まれた。{w}が火を焚いて群れを追い払ったときには、もう手遅れだった。',
item:'針羽虫の標本',itemDesc:'透明な樹脂に閉じ込めた、針のように細い口を持つ小さな羽虫。',
report:'黒い霞の正体'},
{id:'frost_hydra',name:'霜の多頭竜',rare:5,kind:'hostile',
look:'{a}は、氷河の裂け目から立ちのぼる白い息を見つけた。その奥で、氷の鱗に覆われたいくつもの首がゆっくりと持ち上がった。',
habit:'霜の多頭竜は、それぞれの首が別々に眠り、常にどれか一つが見張りに立っていた。{a}は、吐く息が触れたものを一瞬で凍らせることを確かめた。',
deep:'{a}は、多頭竜の首が一つずつ別の個体であることを知った。はるか昔に寄り集まった竜たちは、ひとつの体を分け合って氷の時代を生き延びたのだ。',
good:'{a}は見張りの首が交代するわずかな隙に、氷河の縁から多頭竜を観察した。竜は気づかず、{a}は剥がれ落ちた鱗を拾って戻った。',
bad:'見張りの首が{a}に気づき、凍てつく息を吐きかけた。{a}は岩陰に飛びこんだが、指先と耳にひどい凍傷を負った。',
death:'{v}は、目覚めた多頭竜の吐息を正面から浴びた。{w}が振り返ると、{v}は氷の像のようにその場に立ち尽くしていた。',
item:'多頭竜の氷鱗',itemDesc:'どれだけ温めても決して溶けない、青く透き通った鱗。',
report:'氷河に眠る竜'},
{id:'keeper_crab',name:'甲殻の守り手',rare:2,kind:'symbiotic',
look:'{a}は、浜辺で背中に小さな庭を背負った大きな蟹に出会った。甲羅の上には草花が茂り、小さな虫たちが飛び交っていた。',
habit:'甲殻の守り手は、ほかの生き物を甲羅に住まわせ、その代わりに体を掃除してもらっていた。{a}は、蟹が住人を守るために外敵と戦う姿を見た。',
deep:'{a}は、守り手が船を新しい甲羅だと思っているらしいことに気づいた。蟹は、船ごと住人として迎え入れようと、たびたび船体に寄り添ってきた。',
good:'{a}が甲羅の草を手入れしてやると、守り手は満足げに鋏を鳴らした。それからしばらく、蟹は船の周りを見張ってくれた。',
bad:'{a}が甲羅の住人を一匹つまみ上げると、守り手は怒って鋏を振るった。{a}の腕には、くっきりとした鋏の跡が残った。',
death:'{v}は、守り手の甲羅に住む生き物を無理に採取しようとした。怒った蟹の大鋏に挟まれ、{w}が駆け寄ったときにはもう遅かった。',
item:'守り手の甲羅片',itemDesc:'脱皮で剥がれた甲羅のかけらで、まだ小さな花が根を張っている。',
report:'庭を背負う蟹との約束'},
{id:'thought_fish',name:'思念魚',rare:3,kind:'symbiotic',
look:'{a}は、水面に頭を出してこちらを見つめる魚に気づいた。額に淡く光る器官があり、見つめ返すと頭の奥がかすかにくすぐったくなった。',
habit:'思念魚は、ほかの生き物の考えを感じ取り、自分の考えをそっと送り返していた。{a}は、魚が水辺の獣たちと危険を知らせ合っているのを知った。',
deep:'{a}は、思念魚が言葉ではなく夢を通して語りかけていることに気づいた。船員たちが見ていた水の夢は、魚たちからの共生の申し出だった。',
good:'{a}が水辺で目を閉じると、思念魚の穏やかな考えが流れこんできた。{a}は、星の安全な場所を教わり、代わりに船の歌を教えた。',
bad:'{a}が思念魚の心に深く入りすぎ、膨大な記憶の波にさらわれた。我に返った{a}は、ひどい頭痛と鼻血に苦しんだ。',
death:'{v}は思念魚との交感に夢中になり、何日も水辺から離れなかった。ある朝、{w}が見つけたとき、{v}は水際で静かに眠ったまま目覚めなかった。',
item:'思念魚の額石',itemDesc:'握ると誰かの穏やかな考えが聞こえる気がする、淡く光る石。',
report:'夢で語る魚'},
{id:'light_eater',name:'光食みの蝶',rare:2,kind:'symbiotic',
look:'{a}は、船の照明に群がる黒い蝶を見つけた。羽は光を吸いこむように暗く、止まった灯りが少しずつ暗くなっていった。',
habit:'光食みの蝶は、光を食べる代わりに鱗粉で周囲の熱を保っていた。{a}は、蝶が集まった場所がいつも冷えずに暖かいことに気づいた。',
deep:'{a}は、蝶たちが船の余った光を食べ、その分だけ船内を暖めようとしていることに気づいた。光食みは船を、互いに助け合える相手と見なしていた。',
good:'{a}が使わない照明を蝶に分けると、蝶は船の壁一面に止まって羽を広げた。その夜、冷えきっていた船倉が穏やかに暖まった。',
bad:'{a}が蝶を追い払おうとすると、群れが一斉に鱗粉を撒いた。{a}は咳きこみ、しばらく喉の痛みが取れなかった。',
death:'{v}は、灯りを抱えたまま光食みの蝶の大群に包まれた。光を失った暗闇で足を踏み外し、{v}は深い亀裂へ落ちていった。',
item:'光食みの鱗粉',itemDesc:'小瓶の中でほんのりと温かい、黒く細かな鱗粉。',
report:'光と熱の取り引き'},
{id:'bond_coral',name:'契り珊瑚',rare:4,kind:'symbiotic',
look:'{a}は、浅瀬に広がる珊瑚の森を見つけた。枝の一本一本が脈打つように光り、近づくと枝先がこちらへ向きを変えた。',
habit:'契り珊瑚は、触れた生き物の体に細い枝を根づかせ、その生き物の傷を癒していた。{a}は、珊瑚に寄り添って暮らす魚たちが病気知らずであることを確かめた。',
deep:'{a}は、珊瑚と契った生き物が、珊瑚の記憶を共有することを知った。この星の生き物たちは、珊瑚を通じて遠い祖先の記憶まで受け継いでいた。',
good:'{a}が珊瑚の枝に手を触れると、小さな傷がみるみるうちに塞がった。珊瑚は穏やかに光り、契りの証として枝をひとつ差し出した。',
bad:'{a}が無理に珊瑚を折り取ると、枝先から鋭い棘が伸びて手に刺さった。傷口は珊瑚色に腫れ、熱を出した{a}は数日寝込んだ。',
death:'{v}は珊瑚の森の奥で、契りの枝に全身を絡め取られた。{w}が見つけたとき、{v}は珊瑚の一部となって静かに光っていた。',
item:'契り珊瑚の枝',itemDesc:'持ち主の脈に合わせてゆっくりと光る、淡い桃色の珊瑚の枝。',
report:'記憶を結ぶ珊瑚礁'},
{id:'mind_spore',name:'囁く胞子',rare:3,kind:'parasite',
look:'{a}は、空気中にきらきらと漂う金色の粉に気づいた。耳を澄ますと、粉の舞う方から誰かの囁き声が聞こえる気がした。',
habit:'囁く胞子は、生き物に吸いこまれると脳に根を張り、宿主を胞子の多い場所へ誘っていた。{a}は、同じ方向へふらふらと歩く獣の群れを目撃した。',
deep:'{a}は、胞子の囁きが宿主自身の声を真似ていることに気づいた。宿主は、それが自分の考えだと信じたまま、胞子の望む場所へ歩いていたのだ。',
good:'{a}は防護マスクを固く締め、胞子を密閉容器に封じこめた。容器の中で胞子は、いつまでも小さく囁き続けていた。',
bad:'{a}はマスクの隙間から胞子を吸いこみ、知らない声に導かれて森をさまよった。仲間に連れ戻された{a}は、数日うなされ続けた。',
death:'{v}は胞子に心を奪われ、夜のうちに一人で船を出ていった。{w}が足跡を追った先には、金色の粉に覆われた{v}が横たわっていた。',
item:'囁く胞子の封瓶',itemDesc:'耳を近づけると、中から自分の声のような囁きが聞こえる密閉瓶。',
report:'内なる声の正体'},
{id:'silver_leech',name:'銀蛭',rare:1,kind:'parasite',
look:'{a}は、湿った岩の表面に銀色の細長い生き物が貼りついているのを見つけた。指ほどの大きさで、ぬるりと光を反射していた。',
habit:'銀蛭は、通りかかる生き物の皮膚に気づかれないよう吸いつき、少しずつ体液を吸っていた。{a}は、吸いつく瞬間に痛みを消す液を出すことを知った。',
deep:'{a}は、銀蛭が宿主の体内から金属を集めていることを突き止めた。蛭たちの銀色の体は、何代もの宿主から吸い集めた微量の金属でできていた。',
good:'{a}は塩を撒いて岩場の銀蛭を引き剥がし、無事に何匹かを標本瓶へ収めた。瓶の中で、銀蛭は鏡のように光っていた。',
bad:'探索から戻った{a}の背中に、銀蛭が何匹も吸いついていた。引き剥がしたあと、{a}は貧血でしばらく足元がふらついた。',
death:'{v}は、銀蛭の群れが潜む沼で足を取られ、身動きできないまま無数に吸いつかれた。{w}が引き上げたとき、{v}の顔はひどく青ざめていた。',
item:'銀蛭の標本瓶',itemDesc:'銀色に光る細長い蛭を数匹、薬液に沈めた小瓶。',
report:'銀色の吸血者'},
{id:'hollow_mask',name:'仮面虫',rare:5,kind:'parasite',
look:'{a}は、地面に落ちた白い仮面のようなものを見つけた。顔の形をしたそれには目の穴が二つあり、のぞきこむと、ゆっくりと瞬きをした。',
habit:'仮面虫は、眠っている生き物の顔に張りつき、その体を操って移動していた。{a}は、仮面をつけた獣たちが、まるで別の生き物のように振る舞うのを見た。',
deep:'{a}は、仮面虫がかつてこの星を治めた種族の成れの果てだと知った。体を失った仮面虫たちは、他者の顔を借りて文明の記憶をつなぎとめていたのだ。',
good:'{a}は眠らないよう交代で見張りを立て、仮面虫を慎重に観察した。誰にも張りつけなかった仮面虫は、静かに地面へ潜っていった。',
bad:'{a}がうたた寝した隙に、仮面虫が顔へ張りついた。仲間が慌てて引き剥がしたが、{a}はそれから数日、自分の名前を思い出せなかった。',
death:'{v}は夜のうちに仮面虫に顔を覆われ、朝には別人のように船を出ていった。{w}が呼びかけても、{v}は一度も振り返らなかった。',
item:'抜け殻の仮面',itemDesc:'仮面虫が残した白い殻で、裏側には見知らぬ文字が刻まれている。',
report:'顔を借りる者たち'},
{id:'singing_moss',name:'歌う苔',rare:1,kind:'plant',
look:'{a}は、岩肌を覆う青緑の苔の上で、かすかな歌声を聞いた。風が吹くたびに苔がそよぎ、音が高くなったり低くなったりした。',
habit:'歌う苔は、細かな穂を震わせて音を出し、胞子を運ぶ小さな虫を呼び寄せていた。{a}は、晴れた日ほど歌が明るい調子になることに気づいた。',
deep:'{a}は、苔の歌が星じゅうでつながった一曲だと知った。離れた岩場の苔どうしが歌を引き継ぎ、星を一周して、また最初の旋律に戻っていた。',
good:'{a}が苔のそばで静かに耳を傾けると、歌はやさしい子守歌のような調子に変わった。{a}は、その一節をそっと録音した。',
bad:'{a}が苔をむしり取ると、苔は甲高い音を発した。耳をつんざく音に{a}は倒れこみ、しばらく片耳が聞こえなかった。',
death:'{v}は、歌う苔に覆われた岩棚で眠りこんでしまった。夜の冷えこみのなか、{v}は苔の子守歌に包まれたまま二度と目覚めなかった。',
item:'歌う苔の鉢',itemDesc:'小鉢に移した苔で、船の中でも小さく歌い続けている。',
report:'星をめぐる一曲'},
{id:'memory_tree',name:'記憶樹',rare:3,kind:'plant',
look:'{a}は、丘の上にただ一本そびえる巨木を見上げた。白い樹皮には絵のような模様が浮かび、葉は風もないのにざわめいていた。',
habit:'記憶樹は、根に触れた生き物の記憶を吸い上げ、樹皮の模様として刻んでいた。{a}は、樹皮の模様が毎日少しずつ書き換わっていることを確かめた。',
deep:'{a}は、樹皮の奥に船の仲間たちの顔が刻まれているのを見つけた。記憶樹は、この星に降りた者すべてを覚え、決して忘れないのだった。',
good:'{a}が根元に手を当てると、懐かしい故郷の景色が頭の中に広がった。記憶樹は、代わりに{a}の思い出をひとつ、静かに受け取った。',
bad:'{a}が根に触れた瞬間、他人の記憶が一気に流れこんできた。{a}は意識を失い、目覚めたあともしばらく混乱が続いた。',
death:'{v}は記憶樹の根元に座りこみ、そのまま記憶を吸われ続けた。{w}が見つけたとき、樹皮には{v}の穏やかな顔が新しく刻まれていた。',
item:'記憶樹の葉',itemDesc:'透かして見ると、誰かの思い出の一場面が浮かぶ白い葉。',
report:'忘れない木'},
{id:'ember_fungus',name:'熾火茸',rare:2,kind:'plant',
look:'{a}は、薄暗い洞窟の床一面に赤く光る茸を見つけた。傘の裏から熱気が立ちのぼり、近づくと頬がほんのりと温かくなった。',
habit:'熾火茸は、地中の熱を吸い上げて傘から放ち、洞窟の中を暖めていた。{a}は、寒い夜になると小さな生き物が茸のまわりに集まってくるのを見た。',
deep:'{a}は、熾火茸の菌糸が星の地下深くまで張り巡らされていることを知った。茸たちは、冷えゆく星の熱を少しずつ地表へ運び、命を温め続けていた。',
good:'{a}は耐熱手袋をはめ、熾火茸を傷つけないよう丁寧に一株掘り出した。持ち帰った茸は、船の片隅で小さな暖炉のように光った。',
bad:'{a}が素手で茸に触れると、傘から熱い胞子が噴き出した。{a}は手と顔にやけどを負い、急いで洞窟の外へ逃れた。',
death:'{v}は熾火茸の群生地で、充満した熱と胞子に巻かれて倒れた。{w}が洞窟の奥へ踏みこんだとき、{v}はもう息をしていなかった。',
item:'熾火茸の株',itemDesc:'掌の上でじんわりと温かい、赤く灯る小さな茸。',
report:'地の熱を運ぶ茸'}
];
})();
});
;
