var esc=best(S,'fight',[lead]),out=[lead];
if(esc&&live(S).length>2&&S.rng()<0.75)out.push(esc);
if(live(S).length>4&&S.rng()<0.4){var x=live(S).filter(function(p){return out.indexOf(p)<0;});if(x.length)out.push(S.rng.pick(x));}
